UPDATE "BSCL.Plataforma.BD::ACC.Sesion" SET "TokenValido" = 'N' WHERE "IdUsuario" = :IdUsuario AND "IdCanal" = :IdCanal AND "TokenValido" = 'S' AND ( SELECT "Valor" FROM "BSCL.Plataforma.BD::PLA.Configuracion" WHERE "CodigoParametro" = 'PLA.SesionUnicaUsuario' ) = 'S' AND EXISTS ( SELECT 1 FROM "BSCL.Plataforma.BD::PLA.Configuracion" c WHERE c."CodigoParametro" = 'PLA.CanalesSesionUnica' AND ';' || c."Valor" || ';' LIKE '%;' || "IdCanal" || ';%' )